use std::{path::PathBuf,time::Instant};
use sp1_sdk::{CpuProver,Prover,HashableKey,SP1Stdin};
fn main(){let a:Vec<String>=std::env::args().collect();assert_eq!(a.len(),3);let elf=std::fs::read(&a[1]).unwrap();let out=PathBuf::from(&a[2]);std::fs::create_dir_all(&out).unwrap();let start=Instant::now();let c=CpuProver::new();let(_,vk)=c.setup(&elf);let setup=start.elapsed().as_secs_f64();let exec=Instant::now();let(pv,report)=c.execute(&elf,&SP1Stdin::new()).cycle_limit(100_000_000).run().expect("bounded real portable WAVM guest execution");let bytes=pv.to_vec();assert!(bytes.starts_with(b"GL3/WAVM/PORTABILITY/1"));let r=serde_json::json!({"executionPassed":true,"proofGenerated":false,"publicValues":format!("0x{}",hex::encode(bytes)),"programVKey":vk.bytes32(),"setupSeconds":setup,"executionSeconds":exec.elapsed().as_secs_f64(),"instructionCount":report.total_instruction_count(),"cycleLimit":100_000_000,"report":format!("{report:?}"),"scope":"canonical WAVM arithmetic/runtime portability only, NOT fullSTF or Stylus/LLM proof"});std::fs::write(out.join("execution.json"),serde_json::to_vec_pretty(&r).unwrap()).unwrap();println!("{}",r);}
